import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"Strategy guide","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/STRATEGIES.html"}],["meta",{"property":"og:title","content":"Strategy guide | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/STRATEGIES.html"}],["meta",{"name":"twitter:title","content":"Strategy guide | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"STRATEGIES.md","filePath":"STRATEGIES.md","lastUpdated":1793950336000}`),a={name:`STRATEGIES.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="strategy-guide" tabindex="-1">Strategy guide <a class="header-anchor" href="#strategy-guide" aria-label="Permalink to “Strategy guide”">​</a></h1><p>FD Cal separates strategy documentation by simulation objective. Strategies are not assumed to be interchangeable across objectives.</p><h2 id="scoped-range" tabindex="-1">Scoped Range <a class="header-anchor" href="#scoped-range" aria-label="Permalink to “Scoped Range”">​</a></h2><p>All four currently supported strategies optimise the selected date range: maximise the portfolio outcome within the user&#39;s start and end dates, subject to cash-flow, liquidity, FD eligibility and transfer constraints.</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Search method</th><th>Typical use</th><th>Optimality</th></tr></thead><tbody><tr><td><strong>Greedy</strong></td><td>Immediate SPLIT / CONSOLIDATE / CARRY decisions.</td><td>Fast, deterministic baseline.</td><td>Heuristic; no proof</td></tr><tr><td><strong>GSS</strong></td><td>Recursive SPLIT / CONSOLIDATE planning with liquidity-aware waits.</td><td>Recursive scoped plans with interim investments.</td><td>Heuristic; no proof</td></tr><tr><td><strong>Absolute R</strong></td><td>Exhaustive branch-and-bound over the scoped decision space.</td><td>CLI-only exhaustive search and optimality proof on tractable scenarios.</td><td>Proven when search completes with valid bounds</td></tr><tr><td><strong>Absolute R+</strong></td><td>Bounded layered beam search with local-branch and state controls.</td><td>Practical search when exhaustive exploration is too expensive.</td><td>Proven only when search completes without truncation</td></tr></tbody></table><h3 id="technical-references" tabindex="-1">Technical references <a class="header-anchor" href="#technical-references" aria-label="Permalink to “Technical references”">​</a></h3><ul><li><a href="./strategies/GREEDY.html">Greedy</a></li><li><a href="./strategies/GSS.html">GSS</a></li><li><a href="./strategies/ABSOLUTE.html">Absolute R</a></li><li><a href="./strategies/ABSOLUTE-PLUS.html">Absolute R+</a></li></ul><h3 id="scoped-range-benchmark" tabindex="-1">Scoped Range benchmark <a class="header-anchor" href="#scoped-range-benchmark" aria-label="Permalink to “Scoped Range benchmark”">​</a></h3><p>See the <a href="./strategies/benchmarks.html#scoped-range">Scoped Range sensitivity benchmark</a> for the shared scenario, bank catalogues, graphs, findings and reproducibility details.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p><strong>Status: Under development — no benchmark data available yet.</strong></p><p>Goal-based net-interest optimisation is disabled in the browser and rejected by the public configuration validator and JSON schema. No Goal strategy is currently selectable and no Goal performance data is published.</p><p>The intended first Goal optimiser is <strong>Absolute R</strong>, using an earliest-authoritative-credit objective. Greedy, GSS and Absolute R+ remain scoped-range strategies; they are not dual-optimised.</p><h2 id="simulation-boundary" tabindex="-1">Simulation boundary <a class="header-anchor" href="#simulation-boundary" aria-label="Permalink to “Simulation boundary”">​</a></h2><p>The simulation runtime owns chronological event processing, actual account balances, FD cash flows and maturities, outflow settlement, transfer execution, result construction and finalisation. Strategies own hypothetical planning and decision selection. The runtime validates and executes their decisions.</p><p>All currently supported public runs use the selected scoped start and end dates. The final consolidation sweep occurs once after the scoped horizon completes.</p>`,16)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};